<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from "vue";
import { CalendarPlus, Copy, KeyRound, LoaderCircle, MailPlus, Pencil, Plus, RefreshCw, Search, ShieldCheck, Trash2, Unlink, UserCheck, UsersRound, X } from "lucide-vue-next";
import ConfirmModal from "@/components/operations/ConfirmModal.vue";
import DataPanel from "@/components/operations/DataPanel.vue";
import OpsModal from "@/components/operations/OpsModal.vue";
import StatusBadge from "@/components/operations/StatusBadge.vue";
import { operationsRepository } from "@/data/repositories/operationsRepository";
import type { UiAccessRecord, UiInstituteRecord, UiPendingInvitation, UiStudentRecord, UiUserRecord } from "@/data/models/operations";
import { currentUser } from "@/lib/api";
import EducatorAccessModal from "@/components/operations/EducatorAccessModal.vue";
import ParentAccessModal from "@/components/operations/ParentAccessModal.vue";

type PeopleTab = "all" | "pending_invitations" | "students" | "parents" | "teachers" | "tutors" | "institute_admins" | "institute_staff" | "system_admins" | "system_staff";
type PeopleTabDefinition = { id: PeopleTab; label: string; role: string | null; studentProfiles?: boolean };

const peopleTabs: PeopleTabDefinition[] = [
  { id: "all", label: "All users", role: null },
  { id: "pending_invitations", label: "Pending Invitations", role: null },
  { id: "students", label: "Students", role: "student", studentProfiles: true },
  { id: "parents", label: "Parents", role: "parent" },
  { id: "teachers", label: "Teachers", role: "teacher" },
  { id: "tutors", label: "Tutors", role: "tutor" },
  { id: "institute_admins", label: "Institute admins", role: "institute_admin" },
  { id: "institute_staff", label: "Institute staff", role: "institute_staff" },
  { id: "system_admins", label: "System admins", role: "system_admin" },
  { id: "system_staff", label: "System staff", role: "system_staff" },
];

const tab = ref<PeopleTab>("all"); const loading = ref(true); const saving = ref(false); const confirming = ref(false); const error = ref(""); const notice = ref(""); const search = ref("");
const navigator = window.navigator;
const showForm = ref(false); const editingUserId = ref<number | null>(null); const studentEditor = ref<UiStudentRecord | null>(null); const users = ref<UiUserRecord[]>([]); const students = ref<UiStudentRecord[]>([]); const roles = ref<UiAccessRecord[]>([]); const institutes = ref<UiInstituteRecord[]>([]); const roleUser = ref<UiUserRecord | null>(null);
const actionTarget = ref<{ type: "user" | "student"; item: UiUserRecord | UiStudentRecord } | null>(null);
const roleForm = reactive({ slug: "student", context_type: "system" as "system" | "institute", context_id: 0 });
const inviteOpen = ref(false); const inviteLink = ref(""); const inviteForm = reactive({ email: "", role_slug: "teacher" as "teacher" | "tutor", institute_id: 0 }); const accessUser = ref<UiUserRecord | null>(null); const accessInstituteId = ref(0);
const parentStudent = ref<UiStudentRecord | null>(null);
const pendingInvitations = ref<UiPendingInvitation[]>([]); const invitationBusy = ref("");
const userDefaults = { name: "", email: "", password: "", status: "active", timezone: "UTC", locale: "en" }; const form = reactive({ ...userDefaults });
const studentForm = reactive({ course_id: null as number | null, exam_board_id: null as number | null, school_year: "", school_name: "", status: "active", preferences: {}, metadata: {}, subject_ids: [] as number[] });
const canManageUsers = computed(() => currentUser()?.roles?.some((role) => ["system_admin", "system_staff"].includes(role.slug)) ?? false);
const canAssignRoles = computed(() => currentUser()?.roles?.some((role) => role.slug === "system_admin") ?? false); const selectedRole = computed(() => roles.value.find((role) => role.slug === roleForm.slug));
const canManageParents = computed(() => currentUser()?.roles?.some((role) => role.slug === "system_admin") ?? false);
watch(selectedRole, (role) => { roleForm.context_type = role?.scope === "institute" ? "institute" : "system"; if (roleForm.context_type === "system") roleForm.context_id = 0; });
const activePeopleTab = computed(() => peopleTabs.find((item) => item.id === tab.value) ?? peopleTabs[0]!);
const filteredUsers = computed(() => users.value.filter((item) => {
  const role = activePeopleTab.value.role;
  const belongsToTab = !role || item.roles.some((assignment) => assignment.slug === role);
  return belongsToTab && `${item.name} ${item.email}`.toLowerCase().includes(search.value.toLowerCase());
}));
const filteredStudents = computed(() => students.value.filter((item) => `${item.name} ${item.email} ${item.schoolName}`.toLowerCase().includes(search.value.toLowerCase())));
const filteredInvitations = computed(() => pendingInvitations.value.filter((item) => `${item.email} ${item.role} ${item.type} ${item.context}`.toLowerCase().includes(search.value.toLowerCase())));
function tabCount(item: PeopleTabDefinition) {
  if (item.id === "pending_invitations") return pendingInvitations.value.length;
  if (item.studentProfiles) return students.value.length;
  if (!item.role) return users.value.length;
  return users.value.filter((user) => user.roles.some((assignment) => assignment.slug === item.role)).length;
}
async function load() { loading.value = true; error.value = ""; try { const base = [operationsRepository.users({ per_page: 100 }), operationsRepository.students({ per_page: 100 })] as const; const [userPage, studentPage] = await Promise.all(base); users.value = userPage.items; students.value = studentPage.items; if (canAssignRoles.value) { const [rolePage, institutePage] = await Promise.all([operationsRepository.roles({ per_page: 100 }), operationsRepository.institutes({ per_page: 100 })]); roles.value = rolePage.items; institutes.value = institutePage.items; } if (canManageUsers.value) { pendingInvitations.value = (await operationsRepository.pendingInvitations()).data; } } catch (reason) { error.value = reason instanceof Error ? reason.message : "Unable to load people."; } finally { loading.value = false; } }
function openCreate() { editingUserId.value = null; Object.assign(form, userDefaults); showForm.value = true; }
function openEducatorInvite(role?: "teacher" | "tutor") { if (role) inviteForm.role_slug = role; inviteOpen.value = true; }
function openUserEdit(user: UiUserRecord) { editingUserId.value = user.id; Object.assign(form, { name: user.name, email: user.email, password: "", status: user.status, timezone: user.timezone, locale: user.locale }); showForm.value = true; }
function openStudentEdit(student: UiStudentRecord) { studentEditor.value = student; Object.assign(studentForm, { course_id: student.courseId, exam_board_id: student.examBoardId, school_year: student.schoolYear, school_name: student.schoolName, status: student.status, preferences: {}, metadata: {}, subject_ids: student.subjectIds }); }
function openRoles(user: UiUserRecord) { roleUser.value = user; const existing = user.roles[0]; roleForm.slug = existing?.slug || "student"; roleForm.context_type = existing?.instituteId ? "institute" : "system"; roleForm.context_id = existing?.instituteId || 0; }
async function saveRoles() { if (!roleUser.value) return; saving.value = true; error.value = ""; try { await operationsRepository.assignRoles(roleUser.value.id, [{ slug: roleForm.slug, context_type: roleForm.context_type, context_id: roleForm.context_type === "institute" ? roleForm.context_id : null }]); roleUser.value = null; await load(); } catch (reason) { error.value = reason instanceof Error ? reason.message : "Unable to assign role."; } finally { saving.value = false; } }
async function saveUser() { saving.value = true; error.value = ""; const payload: Record<string, unknown> = { name: form.name, email: form.email, status: form.status, timezone: form.timezone, locale: form.locale }; if (form.password) payload.password = form.password; try { if (editingUserId.value) await operationsRepository.update("users", editingUserId.value, payload); else await operationsRepository.create("users", { ...payload, password: form.password }); showForm.value = false; await load(); } catch (reason) { error.value = reason instanceof Error ? reason.message : "Unable to save user."; } finally { saving.value = false; } }
async function saveStudent() { if (!studentEditor.value) return; saving.value = true; try { await operationsRepository.update("students", studentEditor.value.id, studentForm); studentEditor.value = null; await load(); } catch (reason) { error.value = reason instanceof Error ? reason.message : "Unable to update student."; } finally { saving.value = false; } }
async function confirmAction() { if (!actionTarget.value) return; confirming.value = true; try { if (actionTarget.value.type === "user") await operationsRepository.remove("users", actionTarget.value.item.id); else await operationsRepository.detachStudent(actionTarget.value.item.id); actionTarget.value = null; await load(); } catch (reason) { error.value = reason instanceof Error ? reason.message : "Unable to complete action."; } finally { confirming.value = false; } }
async function inviteEducator() { saving.value = true; error.value = ""; try { const response = await operationsRepository.inviteEducator({ email: inviteForm.email, role_slug: inviteForm.role_slug, institute_id: inviteForm.institute_id || null }); inviteLink.value = `${window.location.origin}${response.activation_path}`; } catch (reason) { error.value = reason instanceof Error ? reason.message : "Unable to invite educator."; } finally { saving.value = false; } }
function closeInvite() { inviteOpen.value = false; inviteLink.value = ""; inviteForm.email = ""; }
function manageAccess(user: UiUserRecord) { accessUser.value = user; accessInstituteId.value = user.roles.some((role) => role.slug === "tutor") ? 0 : (user.roles.find((role) => role.instituteId)?.instituteId || institutes.value[0]?.id || 0); }
async function invitationAction(invite: UiPendingInvitation, action: "activate" | "copy" | "resend" | "extend" | "revoke") {
  const key = `${invite.type}:${invite.id}:${action}`; invitationBusy.value = key; error.value = ""; notice.value = "";
  try {
    if (action === "activate") { await operationsRepository.activateInvitation(invite.type, invite.id); notice.value = "Invitation activated manually."; }
    if (action === "copy") { const response = await operationsRepository.invitationLink(invite.type, invite.id); await navigator.clipboard.writeText(`${window.location.origin}${response.data.activation_path}`); notice.value = "Activation link copied."; }
    if (action === "resend") { await operationsRepository.resendInvitation(invite.type, invite.id); notice.value = "Invitation resent."; }
    if (action === "extend") { await operationsRepository.extendInvitation(invite.type, invite.id, 7); notice.value = "Invitation expiry extended by 7 days."; }
    if (action === "revoke") { await operationsRepository.revokeInvitation(invite.type, invite.id); notice.value = "Invitation revoked."; }
    if (action !== "copy") await load();
  } catch (reason) { error.value = reason instanceof Error ? reason.message : "Unable to manage invitation."; } finally { invitationBusy.value = ""; }
}
function invitationActionBusy(invite: UiPendingInvitation, action: string) { return invitationBusy.value === `${invite.type}:${invite.id}:${action}`; }
onMounted(load);
</script>

<template><div class="space-y-5"><div class="flex flex-wrap items-end justify-between gap-3"><div><p class="text-[12px] font-semibold uppercase tracking-[0.12em] text-violet">Identity & learning</p><h2 class="mt-1 text-[26px] font-bold tracking-[-0.035em]">People</h2><p class="mt-1 text-[13px] text-ink3">Manage every user type, account access, and student ownership record.</p></div><div v-if="!['students', 'pending_invitations'].includes(tab)" class="flex gap-2"><button v-if="['all', 'teachers', 'tutors'].includes(tab)" class="ops-button-secondary flex items-center gap-2" @click="openEducatorInvite(tab === 'teachers' ? 'teacher' : tab === 'tutors' ? 'tutor' : undefined)"><MailPlus :size="15" /> Invite teacher/tutor</button><button class="ops-button-primary flex items-center gap-2 transition hover:-translate-y-0.5 hover:shadow-md" @click="openCreate"><Plus :size="15" /> Add user</button></div></div><p v-if="error" class="rounded-xl bg-pink-light px-4 py-3 text-[13px] text-pink">{{ error }}</p><p v-if="notice" class="rounded-xl bg-mint-light px-4 py-3 text-[13px] text-mint">{{ notice }}</p><div class="flex flex-wrap items-center justify-between gap-3 rounded-2xl border border-border bg-bg-card p-3"><div class="flex max-w-full gap-1 overflow-x-auto rounded-xl bg-bg-soft p-1"><button v-for="item in peopleTabs" :key="item.id" class="flex shrink-0 items-center gap-2 rounded-lg px-3 py-2 text-[12px] font-semibold transition" :class="tab === item.id ? 'bg-bg-card text-blue shadow-sm' : 'text-ink3'" @click="tab = item.id"><span>{{ item.label }}</span><span class="rounded-full bg-bg px-1.5 py-0.5 text-[10px] text-ink3">{{ tabCount(item) }}</span></button></div><label class="flex min-w-[260px] items-center gap-2 rounded-xl border border-border bg-bg px-3 py-2"><Search :size="15" class="text-ink4" /><input v-model="search" class="w-full bg-transparent text-[12px] outline-none" :placeholder="`Search ${activePeopleTab.label.toLowerCase()}`" /></label></div>
  <DataPanel v-if="tab !== 'students' && tab !== 'pending_invitations'" :title="activePeopleTab.label" :description="`${filteredUsers.length} accounts shown`" :loading="loading" :empty="!filteredUsers.length"><div v-if="tab !== 'students'" class="overflow-x-auto"><table class="w-full min-w-[800px] text-left text-[12px]"><thead class="bg-bg-soft text-ink3"><tr><th class="px-5 py-3">User</th><th class="px-4 py-3">Roles</th><th class="px-4 py-3">Last login</th><th class="px-4 py-3">Status</th><th class="px-5 py-3 text-right">Actions</th></tr></thead><tbody class="divide-y divide-border"><tr v-for="user in filteredUsers" :key="user.id" class="transition hover:bg-bg-soft/70"><td class="px-5 py-3.5"><p class="font-semibold text-ink">{{ user.name }}</p><p class="text-ink3">{{ user.email }}</p></td><td class="px-4 py-3.5 text-ink2">{{ user.roles.map((role) => role.slug.replaceAll('_', ' ')).join(', ') || 'Unassigned' }}</td><td class="px-4 py-3.5 text-ink3">{{ user.lastLoginAt ? new Date(user.lastLoginAt).toLocaleString() : 'Never' }}</td><td class="px-4 py-3.5"><StatusBadge :value="user.status" /></td><td class="px-5 py-3.5"><div class="flex justify-end gap-1"><button class="ops-icon-button" title="Edit user" @click="openUserEdit(user)"><Pencil :size="14" /></button><button v-if="user.roles.some((role) => ['teacher', 'tutor'].includes(role.slug))" class="ops-icon-button" title="Manage scoped access" @click="manageAccess(user)"><KeyRound :size="14" /></button><button v-if="canAssignRoles" class="ops-icon-button" title="Assign role" @click="openRoles(user)"><ShieldCheck :size="14" /></button><button class="ops-icon-button hover:bg-pink-light hover:text-pink" title="Deactivate user" @click="actionTarget = { type: 'user', item: user }"><Trash2 :size="14" /></button></div></td></tr></tbody></table></div></DataPanel>
  <DataPanel v-else-if="tab === 'students'" title="Student profiles" :description="`${filteredStudents.length} profiles shown`" :loading="loading" :empty="!filteredStudents.length"><div class="overflow-x-auto"><table class="w-full min-w-[920px] text-left text-[12px]"><thead class="bg-bg-soft text-ink3"><tr><th class="px-5 py-3">Student</th><th class="px-4 py-3">Owner</th><th class="px-4 py-3">Course</th><th class="px-4 py-3">School</th><th class="px-4 py-3">Subjects</th><th class="px-5 py-3 text-right">Actions</th></tr></thead><tbody class="divide-y divide-border"><tr v-for="student in filteredStudents" :key="student.id" class="transition hover:bg-bg-soft/70"><td class="px-5 py-3.5"><p class="font-semibold text-ink">{{ student.name }}</p><p class="text-ink3">{{ student.email }}</p></td><td class="px-4 py-3.5"><StatusBadge :value="student.ownership" /><p v-if="student.instituteName" class="mt-1 text-[10px] text-ink3">{{ student.instituteName }}</p></td><td class="px-4 py-3.5 text-ink2">{{ student.courseName || 'Not set' }}</td><td class="px-4 py-3.5 text-ink2">{{ student.schoolName || 'Not set' }}<p class="text-[10px] text-ink3">{{ student.schoolYear }}</p></td><td class="max-w-[220px] px-4 py-3.5 text-ink2">{{ student.subjectNames.join(', ') || 'None' }}</td><td class="px-5 py-3.5"><div class="flex justify-end gap-1"><button class="ops-icon-button" title="Edit student" @click="openStudentEdit(student)"><Pencil :size="14" /></button><button v-if="student.ownership === 'institute'" class="ops-icon-button" title="Detach" @click="actionTarget = { type: 'student', item: student }"><Unlink :size="14" /></button></div></td></tr></tbody></table></div></DataPanel>
  <DataPanel v-else title="Pending Invitations" :description="`${filteredInvitations.length} invitations awaiting acceptance`" :loading="loading" :empty="!filteredInvitations.length"><div class="overflow-x-auto"><table class="w-full min-w-[1040px] text-left text-[12px]"><thead class="bg-bg-soft text-ink3"><tr><th class="px-5 py-3">Invitee</th><th class="px-4 py-3">Role</th><th class="px-4 py-3">Access</th><th class="px-4 py-3">Expiry</th><th class="px-5 py-3 text-right">Actions</th></tr></thead><tbody class="divide-y divide-border"><tr v-for="invite in filteredInvitations" :key="`${invite.type}-${invite.id}`" class="transition hover:bg-bg-soft/70"><td class="px-5 py-3.5"><p class="font-semibold text-ink">{{ invite.email }}</p><p class="text-ink3">{{ invite.type.replaceAll('_', ' ') }}</p></td><td class="px-4 py-3.5 capitalize text-ink2">{{ invite.role.replaceAll('_', ' ') }}</td><td class="px-4 py-3.5 text-ink2">{{ invite.context }}</td><td class="px-4 py-3.5"><p :class="invite.expired ? 'font-semibold text-pink' : 'text-ink2'">{{ invite.expires_at ? new Date(invite.expires_at).toLocaleString() : 'No expiry' }}</p><p v-if="invite.expired" class="mt-0.5 text-[10px] text-pink">Expired</p></td><td class="px-5 py-3.5"><div class="flex justify-end gap-1"><button class="ops-icon-button text-mint" title="Activate manually" :disabled="Boolean(invitationBusy)" @click="invitationAction(invite, 'activate')"><LoaderCircle v-if="invitationActionBusy(invite, 'activate')" :size="14" class="animate-spin" /><UserCheck v-else :size="14" /></button><button class="ops-icon-button" title="Resend invitation" :disabled="Boolean(invitationBusy)" @click="invitationAction(invite, 'resend')"><LoaderCircle v-if="invitationActionBusy(invite, 'resend')" :size="14" class="animate-spin" /><RefreshCw v-else :size="14" /></button><button class="ops-icon-button" title="Copy activation link" :disabled="Boolean(invitationBusy)" @click="invitationAction(invite, 'copy')"><LoaderCircle v-if="invitationActionBusy(invite, 'copy')" :size="14" class="animate-spin" /><Copy v-else :size="14" /></button><button class="ops-icon-button" title="Extend expiry by 7 days" :disabled="Boolean(invitationBusy)" @click="invitationAction(invite, 'extend')"><LoaderCircle v-if="invitationActionBusy(invite, 'extend')" :size="14" class="animate-spin" /><CalendarPlus v-else :size="14" /></button><button class="ops-icon-button hover:bg-pink-light hover:text-pink" title="Revoke invitation" :disabled="Boolean(invitationBusy)" @click="invitationAction(invite, 'revoke')"><LoaderCircle v-if="invitationActionBusy(invite, 'revoke')" :size="14" class="animate-spin" /><Trash2 v-else :size="14" /></button></div></td></tr></tbody></table></div></DataPanel>
  <OpsModal :open="showForm" max-width="max-w-md" :close-on-backdrop="!saving" @close="showForm = false"><form class="rounded-2xl border border-border bg-bg-card p-5 shadow-2xl" @submit.prevent="saveUser"><div class="mb-5 flex items-start justify-between"><div><h3 class="text-[17px] font-bold">{{ editingUserId ? 'Edit platform user' : 'Create platform user' }}</h3><p class="mt-1 text-[12px] text-ink3">Identity fields are stored in the users table.</p></div><button type="button" :disabled="saving" @click="showForm = false"><X :size="18" /></button></div><div class="space-y-3"><label class="block text-[11px] font-semibold">Name<input v-model="form.name" required class="ops-input" /></label><label class="block text-[11px] font-semibold">Email<input v-model="form.email" required type="email" class="ops-input" /></label><label class="block text-[11px] font-semibold">{{ editingUserId ? 'New password (optional)' : 'Temporary password' }}<input v-model="form.password" :required="!editingUserId" minlength="8" type="password" class="ops-input" /></label><div class="grid grid-cols-2 gap-3"><label class="text-[11px] font-semibold">Status<select v-model="form.status" class="ops-input"><option value="pending">Pending</option><option value="active">Active</option><option value="suspended">Suspended</option><option value="disabled">Disabled</option></select></label><label class="text-[11px] font-semibold">Timezone<input v-model="form.timezone" class="ops-input" /></label></div></div><div class="mt-5 flex justify-end gap-2"><button type="button" class="ops-button-secondary" :disabled="saving" @click="showForm = false">Cancel</button><button :disabled="saving" class="ops-button-primary inline-flex min-w-28 items-center justify-center gap-2"><LoaderCircle v-if="saving" :size="14" class="animate-spin" />{{ saving ? 'Saving…' : editingUserId ? 'Update user' : 'Create user' }}</button></div></form></OpsModal>
  <OpsModal :open="Boolean(studentEditor)" max-width="max-w-md" :close-on-backdrop="!saving" @close="studentEditor = null"><form class="rounded-2xl border border-border bg-bg-card p-5 shadow-2xl" @submit.prevent="saveStudent"><div class="mb-5 flex justify-between"><div><h3 class="text-[17px] font-bold">Edit student profile</h3><p class="mt-1 text-[12px] text-ink3">{{ studentEditor?.name }}</p></div><button type="button" @click="studentEditor = null"><X :size="18" /></button></div><div class="space-y-3"><label class="text-[11px] font-semibold">School year<input v-model="studentForm.school_year" class="ops-input" /></label><label class="text-[11px] font-semibold">School name<input v-model="studentForm.school_name" class="ops-input" /></label><label class="text-[11px] font-semibold">Status<select v-model="studentForm.status" class="ops-input"><option value="active">Active</option><option value="inactive">Inactive</option><option value="suspended">Suspended</option></select></label></div><div class="mt-5 flex justify-end gap-2"><button type="button" class="ops-button-secondary" @click="studentEditor = null">Cancel</button><button :disabled="saving" class="ops-button-primary inline-flex min-w-28 items-center justify-center gap-2"><LoaderCircle v-if="saving" :size="14" class="animate-spin" />{{ saving ? 'Saving…' : 'Update student' }}</button></div></form></OpsModal>
  <OpsModal :open="Boolean(roleUser)" max-width="max-w-md" :close-on-backdrop="!saving" @close="roleUser = null"><form class="rounded-2xl border border-border bg-bg-card p-5 shadow-2xl" @submit.prevent="saveRoles"><div class="mb-5 flex justify-between"><div><h3 class="text-[17px] font-bold">Assign role</h3><p class="mt-1 text-[12px] text-ink3">{{ roleUser?.name }} · replaces the current assignment.</p></div><button type="button" @click="roleUser = null"><X :size="18" /></button></div><div class="space-y-3"><label class="text-[11px] font-semibold">Role<select v-model="roleForm.slug" class="ops-input"><option v-for="role in roles" :key="role.id" :value="role.slug">{{ role.name }}</option></select></label><p class="rounded-xl bg-bg-soft px-3 py-2 text-[11px] text-ink3">Context: {{ selectedRole?.scope === 'institute' ? 'Institute' : 'System' }}</p><label v-if="roleForm.context_type === 'institute'" class="text-[11px] font-semibold">Institute<select v-model.number="roleForm.context_id" required class="ops-input"><option :value="0" disabled>Select institute</option><option v-for="institute in institutes" :key="institute.id" :value="institute.id">{{ institute.name }}</option></select></label></div><div class="mt-5 flex justify-end gap-2"><button type="button" class="ops-button-secondary" @click="roleUser = null">Cancel</button><button class="ops-button-primary inline-flex min-w-28 items-center justify-center gap-2" :disabled="saving"><LoaderCircle v-if="saving" :size="14" class="animate-spin" />{{ saving ? 'Saving…' : 'Assign role' }}</button></div></form></OpsModal>
  <OpsModal :open="inviteOpen" max-width="max-w-md" :close-on-backdrop="!saving" @close="closeInvite"><form class="rounded-2xl border border-border bg-bg-card p-5 shadow-2xl" @submit.prevent="inviteEducator"><div class="mb-5 flex justify-between"><div><h3 class="text-[17px] font-bold">Invite teacher or tutor</h3><p class="mt-1 text-[12px] text-ink3">No public signup is created; the recipient activates access from email.</p></div><button type="button" @click="closeInvite"><X :size="18" /></button></div><template v-if="!inviteLink"><div class="space-y-3"><label class="text-[11px] font-semibold">Email<input v-model="inviteForm.email" required type="email" class="ops-input" /></label><label class="text-[11px] font-semibold">Role<select v-model="inviteForm.role_slug" class="ops-input"><option value="teacher">Teacher</option><option value="tutor">Tutor (AI review only)</option></select></label><label class="text-[11px] font-semibold">Institute (optional)<select v-model.number="inviteForm.institute_id" class="ops-input"><option :value="0">Platform/global</option><option v-for="institute in institutes" :key="institute.id" :value="institute.id">{{ institute.name }}</option></select></label></div><div class="mt-5 flex justify-end gap-2"><button type="button" class="ops-button-secondary" @click="closeInvite">Cancel</button><button :disabled="saving" class="ops-button-primary"><LoaderCircle v-if="saving" :size="14" class="animate-spin" />{{ saving ? 'Sending…' : 'Send invitation' }}</button></div></template><template v-else><div class="rounded-xl bg-mint-light p-4"><p class="text-[12px] font-semibold text-mint">Invitation emailed</p><p class="mt-2 break-all font-mono text-[11px]">{{ inviteLink }}</p></div><button type="button" class="mt-4 flex w-full items-center justify-center gap-2 ops-button-secondary" @click="navigator.clipboard.writeText(inviteLink)"><Copy :size="14" /> Copy activation link</button></template></form></OpsModal>
  <EducatorAccessModal :open="Boolean(accessUser)" :educator="accessUser" :institute-id="accessInstituteId || null" :allow-parent-management="accessUser?.roles.some((role) => role.slug === 'teacher') ?? false" @close="accessUser = null" />
  <ConfirmModal :open="Boolean(actionTarget)" :title="actionTarget?.type === 'user' ? 'Deactivate user?' : 'Detach student?'" :message="actionTarget?.type === 'user' ? `Deactivate ${(actionTarget.item as UiUserRecord).name}? The account and its history will be retained, but sign-in will be disabled.` : `Move ${(actionTarget?.item as UiStudentRecord)?.name || 'this student'} back to platform ownership?`" :confirm-label="actionTarget?.type === 'user' ? 'Deactivate user' : 'Detach student'" :busy="confirming" :tone="'warning'" @close="actionTarget = null" @confirm="confirmAction" />
  <section v-if="tab === 'students' && canManageParents && filteredStudents.length" class="rounded-2xl border border-border bg-bg-card p-5"><h3 class="text-[15px] font-bold">Parent access management</h3><p class="mt-1 text-[12px] text-ink3">Link or revoke parents for any platform or institute student.</p><div class="mt-4 grid gap-2 md:grid-cols-2"><button v-for="student in filteredStudents" :key="student.userId" class="flex items-center justify-between rounded-xl border border-border p-3 text-left transition hover:bg-bg-soft" @click="parentStudent = student"><span><strong class="block text-[12px]">{{ student.name }}</strong><span class="text-[11px] text-ink3">{{ student.email }}</span></span><UsersRound :size="16" class="text-blue" /></button></div></section>
  <ParentAccessModal :open="Boolean(parentStudent)" :student="parentStudent ? { userId: parentStudent.userId, name: parentStudent.name } : null" @close="parentStudent = null" />
</div></template>
